with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '晩鐘', 'ジャン＝フランソワ・ミレー', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/JEAN-FRAN%C3%87OIS_MILLET_-_El_%C3%81ngelus_%28Museo_de_Orsay%2C_1857-1859._%C3%93leo_sobre_lienzo%2C_55.5_x_66_cm%29.jpg/960px-JEAN-FRAN%C3%87OIS_MILLET_-_El_%C3%81ngelus_%28Museo_de_Orsay%2C_1857-1859._%C3%93leo_sobre_lienzo%2C_55.5_x_66_cm%29.jpg', '1857〜59年頃に描かれ、パリのオルセー美術館が所蔵する作品です。夕暮れの畑で、遠くの教会から聞こえる鐘の音に合わせ、農民の夫婦が手を止めて祈りを捧げています。足元には籠に入ったジャガイモ、そばにはフォークと手押し車。逆光の中に浮かぶ二人の姿と、地平線まで続く静かな大地が、日々の労働と祈りの結びつきを感じさせます。のちにサルバドール・ダリがこの絵に強くこだわり、繰り返し題材にしたことでも知られます。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:JEAN-FRANÇOIS_MILLET_-_El_Ángelus_(Museo_de_Orsay,_1857-1859._Óleo_sobre_lienzo,_55.5_x_66_cm).jpg'),
    (2, '三代目大谷鬼次の江戸兵衛', '東洲斎写楽', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/The_actor_Otani_Oniji_II_as_Yakko_Edobei_-_Sharaku_-_TNM.jpg/960px-The_actor_Otani_Oniji_II_as_Yakko_Edobei_-_Sharaku_-_TNM.jpg', '寛政6年（1794）5月、版元・蔦屋重三郎のもとから出された役者大首絵の一枚です。歌舞伎「恋女房染分手綱」で敵役の奴江戸兵衛を演じる三代目大谷鬼次を描いています。両手を突き出して指を広げ、口を固く結んだ表情が、悪役の凄みを誇張して伝えます。背景には黒雲母摺が使われ、人物を際立たせています。写楽はおよそ10か月の間に140点あまりの作品を残して姿を消し、その正体は長く謎とされてきました。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:The_actor_Otani_Oniji_II_as_Yakko_Edobei_-_Sharaku_-_TNM.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('東博でファイナルファンタジー40周年展', '東京国立博物館の表慶館で、所蔵の日本美術とファイナルファンタジーを組み合わせる展覧会が2027年1月に開幕する。', '東京国立博物館の表慶館で、2027年1月8日から4月4日まで「ファイナルファンタジー40周年記念展「終わりなきファンタジーの世界」」が開かれる。同館が所蔵する国宝・重要文化財を中心とした日本美術と、ファイナルファンタジーのキャラクターや世界観を組み合わせる展覧会。菱川師宣《見返り美人図》とFFVIIのセフィロス、葛飾北斎《冨嶽三十六景 神奈川沖浪裏》とFFIXの召喚獣リヴァイアサンを組み合わせた作品などが紹介された。国宝《孔雀明王像》《風神雷神図屏風》とのコラボレーションも予告されている。歴代のアートデザイナー12名が、伝統的な木版の技法から現代の特殊印刷までを用いて制作に参加する。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/headline/33331',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('敦煌とシルクロードの展覧会、横浜で', '横浜ユーラシア文化館で、平山郁夫と江上波夫の足跡をたどる敦煌・シルクロードの展覧会が2027年1月に開幕する。', '横浜ユーラシア文化館（横浜市中区日本大通）で、2027年1月16日から3月28日まで「敦煌・シルクロードの風が立つー平山郁夫と江上波夫の足跡」が開かれる。莫高窟で発見された経典や仏画の図録などの資料から、敦煌の仏教文化を紹介する。あわせて、画家の平山郁夫、小説家の井上靖、東洋学者の江上波夫の3人の交流と業績をたどる。平山郁夫の《敦煌莫高窟》（1983年）をはじめ、シルクロードの文化を伝える品々が並ぶ。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33333',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
