values ('国際美術展「TOKYO ATLAS」10万人突破', '東京・臨海エリアで開催中の国際美術展「TOKYO ATLAS」の来場者が、開幕1か月で10万人を超えた。', '東京・臨海エリアで開かれている国際美術展「TOKYO ATLAS」の来場者数が、開幕から1か月となる11月10日時点で101,032人に達したと、主催者の広報事務局が11月16日に発表した。会期は2026年10月10日から12月20日まで。会場はお台場や青海などの臨海エリアの複数の施設に広がり、入場は無料（一部有料プログラムあり）。会期後半には、11月23日と12月12日に無料のガイドツアー、12月12日から19日にはアブラアム・ポワンシュヴァルによるパフォーマンス、12月19日には青海エリアのクロージングイベントが予定されている。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261116-AEJ3042658/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('金剛全図', 'Geumgang jeondo', '鄭敾', 'Jeong Seon',
        1734,
        (select slug from public.art_movements where slug = 'joseon'),
        'サムスン美術館リウム', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Jeong_Seon-Geumgangjeondo.jpg/960px-Jeong_Seon-Geumgangjeondo.jpg', '1734年、鄭敾が朝鮮半島東部の名山・金剛山の内側の峰々を一望のもとに描いた作品で、韓国の国宝としてソウルのサムスン美術館リウムが所蔵しています。無数の峰を円形にまとめた大胆な構図で、右側の切り立った岩山は鋭い縦の線で、左側のなだらかな土の山は柔らかな点で描き分けられています。中国の画法をなぞって想像の山水を描くのが主流だった時代に、実際に旅して見た朝鮮の風景を描く「真景山水」を切り開いた鄭敾の代表作で、のちの金弘道らの写実的な表現へとつながりました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Jeong_Seon-Geumgangjeondo.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

