insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('檜図屏風', 'Cypress Trees', '狩野永徳', 'Kanō Eitoku',
        1590,
        (select slug from public.art_movements where slug = 'kano'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Kano_Eitoku_-_Cypress_Trees_-_Google_Art_Project.jpg/960px-Kano_Eitoku_-_Cypress_Trees_-_Google_Art_Project.jpg', '狩野永徳が晩年に手がけたとされる作品で、東京国立博物館が所蔵する国宝です。もとは八条宮家の御殿の襖絵として描かれ、のちに屏風に仕立てられました。金地を背景に、太い幹をうねらせて枝を大きく広げる檜の巨木を、画面いっぱいに描いています。岩や水流も力強い筆で表され、豪壮な桃山の障壁画の特色がよく表れています。祖父・狩野元信が整えた和漢を融合させた画法を受け継ぎつつ、天下人の城郭を飾るにふさわしい迫力へと押し広げました。永徳はこの作品と同じ1590年に亡くなりました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Kano_Eitoku_-_Cypress_Trees_-_Google_Art_Project.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
