    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('申潤福', 'Shin Yun-bok', '申潤福',
        1758, null, 'east_asia', array['joseon']::text[],
        '都市に生きる人々、とくに女性の姿を洗練された筆で描いた朝鮮王朝後期の風俗画家。', '朝鮮王朝後期の画家で、号は蕙園。宮廷画家を出した家に生まれ、父の申漢枰も画家でした。王室の絵画を担う図画署に勤めたと伝えられますが、没年は分かっていません。

金弘道が庶民の暮らしを描いたのに対し、申潤福は都市の上流の暮らしに目を向け、両班の男性と妓生との恋愛の場面などを、細い線と鮮やかな色で洗練された風俗画に仕立てました。南宗画風の山水や花鳥も描いています。

30図からなる画帖『蕙園伝神帖』や、一人の女性を描いた「美人図」（ともにソウルの澗松美術館所蔵）が代表作です。「端午図」「月下情人」なども知られ、金弘道とならぶ朝鮮後期の風俗画の担い手とされています。', 'https://ja.wikipedia.org/wiki/%E7%94%B3%E6%BD%A4%E7%A6%8F')
