    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('金弘道', 'Kim Hong-do', '金弘道',
        1745, null, 'east_asia', array['joseon']::text[],
        '庶民の暮らしを生き生きと描く風俗画を確立した、朝鮮王朝後期の宮廷画家。', '朝鮮王朝後期の画家で、号は檀園。当時を代表する文人画家・姜世晃に絵を学び、その推薦で王室の絵画を担う図画署の画員になりました。1773年には、のちの国王・正祖となる王世孫の肖像を描き、正祖の即位後は肖像や行幸の記録画、武芸の書物の挿絵など、多くの仕事を任されました。没年ははっきりしません。

山水・人物・花鳥のどれにも優れましたが、とくに知られるのは、名もない庶民の日常を主題にした風俗画です。背景をほとんど描かず、人物の動きや表情だけで場面の空気を伝える描き方を確立しました。

代表作の『檀園風俗図帖』には「書堂」「シルム」「舞童」「酒幕」などが収められています。ほかに国宝の「群仙図屏」や虎を描いた「松下猛虎図」があり、その風俗画は申潤福らに受け継がれました。', 'https://ja.wikipedia.org/wiki/%E9%87%91%E5%BC%98%E9%81%93')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('狩野元信', 'Kanō Motonobu', '元信',
        1476, 1559, 'japan', array['kano']::text[],
        '漢画とやまと絵を融合させ、狩野派が長く続く土台を築いた室町時代の画家。', '室町時代の画家で、狩野派の祖・狩野正信の子として生まれ、2代目として一門を率いました。のちに「古法眼」と呼ばれます。京都で活動し、室町幕府や朝廷、石山本願寺などの注文を受けたほか、町衆に扇絵を売るなど、幅広い顧客を持ちました。

父から受け継いだ中国風の水墨画（漢画）に、土佐派のやまと絵の要素を取り入れ、和と漢を兼ねる画風を築きました。また、書の書体になぞらえて画法を「真・行・草」の3つに整理し、弟子がその型を学ぶことで、工房として大きな仕事を数多くこなせる仕組みを作りました。書院造の建物にふさわしい障壁画の様式を確立したことも大きな功績です。

大徳寺大仙院の「四季花鳥図」が代表作とされます。ほかに霊雲院の障壁画、「白衣観音図」（ボストン美術館）などが知られ、孫の永徳をはじめ、のちの狩野派の画家たちの基礎となりました。', 'https://ja.wikipedia.org/wiki/%E7%8B%A9%E9%87%8E%E5%85%83%E4%BF%A1')
